/// Hand Trick. Cost 1, Skill, Self. Gain 7 Block (10 upgraded); then
/// select 1 Skill in hand that is not already Sly this turn and mark
/// it Sly for the turn. Mirrors C# `HandTrick.OnPlay`
/// (`../sts2-wiki/decompiled/v0.103.2/.../HandTrick.cs:27-35`):
/// `CreatureCmd.GainBlock(owner, BlockVar(7m), play)` then
/// `CardSelectCmd.FromHand(filter: skill && !IsSlyThisTurn)` →
/// `CardCmd.ApplySingleTurnSly`. OnUpgrade bumps block to 10.
/// Bead `sts2-rs-5om` originally implemented this as "add 3 Shivs",
/// which is the wrong card entirely (likely confusion with `Shuriken`
/// / Python pin drift); bead `sts2-rs-z54pr` replaces with the
/// correct block-gain. Bead `sts2-rs-handtrick-sly` wires the
/// single-turn-Sly card-select arm onto the real pending-choice surface
/// ([`sts2_core::ChoiceKind::ApplySlyInHand`]), mirroring Snap's
/// `ApplyRetainInHand` flow: pick one Skill in hand not already Sly and
/// record it in `player.sly_this_turn` (consulted by the active discard
/// auto-play). `FromHand` auto-applies when `<= 1` Skill is eligible and
/// only opens the selection at `>= 2`.
pub(crate) fn play_hand_trick(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    gain_block_player(state, current_card_block(state));

    // C# `CardSelectCmd.FromHand(prefs(1), filter: Type == Skill &&
    // !IsSlyThisTurn)` → `CardCmd.ApplySingleTurnSly`. IsSlyThisTurn = the
    // card's `Sly` keyword (printed, or added in combat by Master Planner's
    // `ApplyKeyword`) OR an already-applied single-turn Sly: `card_is_sly`.
    // Ignoring Master Planner's Sly offered two already-Sly Skills, so Rust
    // prompted where C# auto-picked the lone candidate (loadout Silent 1150
    // v0.111.0: Nightmare then copied a Shiv instead of Haze).
    let candidates: Vec<sts2_core::CardUid> = state
        .player
        .hand
        .iter()
        .copied()
        .filter(|uid| {
            let idx = uid.0.get() as usize - 1;
            state.cards.get(idx).is_some_and(|c| {
                c.card_type == CardType::Skill
                    && !c.is_quest()
                    && !sts2_core::card_effects::card_is_sly(state, *uid)
            })
        })
        .collect();
    match candidates.as_slice() {
        [] => {}
        // FromHand auto-applies to the lone candidate (cards.Count <= MinSelect).
        &[uid] => {
            state.player.sly_this_turn.push(uid);
        }
        // 2+ candidates: open a single-pick choice in hand order.
        _ => {
            let options: Vec<sts2_core::ChoiceOption> = candidates
                .iter()
                .filter_map(|&uid| {
                    let idx = uid.0.get() as usize - 1;
                    let card = state.cards.get(idx)?;
                    Some(sts2_core::ChoiceOption {
                        card_id: card.card_id,
                        upgraded: card.upgraded,
                        card_uid: Some(uid),
                        source_pile: Some(sts2_core::cards::PileKind::Hand),
                    })
                })
                .collect();
            state.request_card_choice(sts2_core::ChoiceKind::ApplySlyInHand, options, 1, 1, false);
        }
    }
    EffectResult::Resolved
}

